-- Donnees du catalogue web GameStore
-- Source: www/data/games.json
INSERT INTO jeu (
  slug,
  titre,
  description_courte,
  description_longue,
  prix,
  date_sortie,
  image_url,
  download_url
)
VALUES
  ('counter-strike-2', 'Counter-Strike 2', 'Le FPS compétitif ultime, nouvelle génération. (20% de réduction)', 'Counter-Strike 2 modernise la formule competitive culte de Valve avec une architecture graphique plus recente, un gameplay ultra precis et une scene e-sport toujours active. C''est un excellent choix pour les joueurs qui aiment progresser sur la strategie d''equipe, la communication et la maitrise mecanique.', 0.00, '2023-09-27', 'img/games/counter-strike-2.png', 'https://store.steampowered.com/app/730/CounterStrike_2/'),
  ('red-dead-redemption-2', 'Red Dead Redemption 2', 'Western épique en monde ouvert, Rockstar Games. (30% de réduction)', 'Red Dead Redemption 2 propose un immense monde ouvert riche en details, des personnages marquants et une narration cinematographique. Entre missions, exploration libre, chasse, quetes secondaires et decouverte de l''Ouest americain, le jeu offre une aventure longue et immersive.', 59.00, '2018-10-26', 'img/games/red-dead-redemption-2.jpg', 'https://store.steampowered.com/app/1174180/Red_Dead_Redemption_2/'),
  ('silent-hill-2-remake', 'Silent Hill 2 Remake', 'Remake du classique survival horror.', 'Silent Hill 2 Remake reinterprete un classique du survival horror avec une mise en scene plus moderne et une ambiance psychologique oppressante. Le jeu met l''accent sur l''atmosphere, l''exploration et les combats tendus, avec une narration centree sur la culpabilite et le traumatisme.', 79.00, '2024-10-08', 'img/games/silent-hill-2-remake.avif', 'https://store.steampowered.com/app/2124490/SILENT_HILL_2/'),
  ('resident-evil-requiem', 'Resident Evil Requiem', 'Nouvel opus de la saga Resident Evil.', 'Resident Evil Requiem poursuit la tradition de la serie avec de nouvelles zones dangereuses, des ressources limitees et des affrontements intenses. Ce type d''opus melange en general action et horreur de survie avec une progression tendue et de nombreux moments memorables.', 79.00, '2026-02-27', 'img/games/resident-evil-requiem.webp', 'https://www.residentevil.com/requiem/en-us/'),
  ('cyberpunk-2077', 'Cyberpunk 2077', 'RPG futuriste en monde ouvert, CD Projekt. (25% de réduction)', 'Cyberpunk 2077 plonge le joueur dans Night City, une megapole futuriste ou l''ambition, la technologie et la violence cohabitent. Avec ses quetes narratives, ses choix de dialogue et sa progression RPG, le jeu offre plusieurs facons de jouer selon le style que tu preferes.', 39.00, '2020-12-10', 'img/games/cyberpunk-2077.jpg', 'https://store.steampowered.com/app/1091500/Cyberpunk_2077/'),
  ('metal-gear-solid-3', 'Metal Gear Solid 3', 'Classique original d''infiltration et d''espionnage.', 'Metal Gear Solid 3: Snake Eater est le jeu original de 2004, une reference de l''infiltration et de l''espionnage. Il suit Naked Snake dans une mission en pleine jungle, avec une aventure tactique basee sur la discretion, la survie, l''observation et l''adaptation a l''environnement.', 59.00, '2004-11-17', 'img/games/metal-gear-solid-3.jpg', 'https://store.steampowered.com/app/2417610/METAL_GEAR_SOLID_Delta_SNAKE_EATER/'),
  ('the-legend-of-zelda-breath-of-the-wild', 'The Legend of Zelda: Breath of the Wild', 'Aventure épique sur Nintendo Switch. (15% de réduction)', 'Breath of the Wild reinvente l''exploration en monde ouvert avec une grande liberte d''approche. Chaque montagne, sanctuaire ou village invite a la curiosite, et les systemes physiques du jeu permettent des solutions creatives en combat comme en exploration.', 59.00, '2017-03-03', 'img/games/the-legend-of-zelda-breath-of-the-wild.avif', 'https://www.nintendo.com/store/products/the-legend-of-zelda-breath-of-the-wild-switch/'),
  ('god-of-war-ragnarok', 'God of War Ragnarok', 'Suite de l''aventure nordique de Kratos. (10% de réduction)', 'God of War Ragnarok poursuit l''histoire de Kratos et Atreus dans une aventure epique inspiree de la mythologie nordique. Le jeu combine combats nerveux, mise en scene spectaculaire et narration emotionnelle avec des environnements tres soignes.', 59.00, '2022-11-09', 'img/games/god-of-war-ragnarok.webp', 'https://store.steampowered.com/app/2322010/God_of_War_Ragnark/'),
  ('clair-obscur-expedition-33', 'Clair Obscur: Expedition 33', 'RPG français au style artistique unique.', 'Clair Obscur: Expedition 33 mise sur une direction artistique marquee et un univers original. Le jeu propose un RPG narratif ou les combats, la construction de groupe et l''ambiance visuelle contribuent a une experience plus dramatique et immersive.', 79.00, '2025-04-24', 'img/games/clair-obscur-expedition-33.jpg', 'https://store.steampowered.com/app/1903340/Clair_Obscur_Expedition_33/'),
  ('the-last-of-us-part-ii', 'The Last of Us Part II', 'Aventure narrative intense, Naughty Dog. (20% de réduction)', 'The Last of Us Part II est une aventure narrative intense axee sur la survie, les consequences morales et des personnages complexes. Le gameplay alterne infiltration, affrontements brutaux et exploration, avec une mise en scene tres cinematographique.', 49.00, '2020-06-19', 'img/games/the-last-of-us-part-ii.avif', 'https://store.steampowered.com/agecheck/app/2531310/'),
  ('fallout-new-vegas', 'Fallout: New Vegas', 'RPG post-apocalyptique culte. (35% de réduction)', 'Fallout: New Vegas est un RPG culte qui valorise les choix du joueur et leurs consequences. Entre factions rivales, quetes alternatives et dialogues tres riches, il reste une reference pour les amateurs de roleplay et d''univers post-apocalyptique.', 19.00, '2010-10-22', 'img/games/fallout-new-vegas.jpg', 'https://store.steampowered.com/app/22380/Fallout_New_Vegas/'),
  ('the-witcher-3-wild-hunt', 'The Witcher 3: Wild Hunt', 'RPG d''action en monde ouvert, CD Projekt. (20% de réduction)', 'The Witcher 3 combine quetes memorables, combats dynamiques et exploration d''un vaste monde medieval-fantastique. Le jeu se distingue surtout par la qualite de ses histoires secondaires et la profondeur de son univers.', 39.00, '2015-05-19', 'img/games/the-witcher-3-wild-hunt.jpg', 'https://store.steampowered.com/app/292030/The_Witcher_3_Wild_Hunt/'),
  ('grand-theft-auto-v', 'Grand Theft Auto V', 'Action, aventure et chaos à Los Santos. (30% de réduction)', 'GTA V propose une campagne solo ambitieuse, un monde ouvert vivant et un mode en ligne extremement populaire. Entre missions, conduite, activites annexes et contenu communautaire, c''est un jeu tres complet qui se renouvelle facilement.', 29.00, '2013-09-17', 'img/games/grand-theft-auto-v.jpg', 'https://store.steampowered.com/app/271590/Grand_Theft_Auto_V/'),
  ('battlefield-6', 'Battlefield 6', 'Champ de bataille moderne, multijoueur massif.', 'Battlefield mise historiquement sur de grandes batailles multijoueur avec vehicules, destruction et jeu en escouade. Cet opus est pense pour les joueurs qui aiment les affrontements a grande echelle et la cooperation tactique.', 59.00, '2025-10-15', 'img/games/battlefield-6.png', 'https://store.steampowered.com/agecheck/app/2807960/'),
  ('forza-horizon-5', 'Forza Horizon 5', 'Course automobile en monde ouvert au Mexique. (10% de réduction)', 'Forza Horizon 5 offre un monde ouvert vaste et coloré inspire du Mexique, avec une conduite accessible mais exigeante a haut niveau. Les courses, defis, evenements saisonniers et options de personnalisation en font une reference arcade-simulation.', 49.00, '2021-11-09', 'img/games/forza-horizon-5.jpg', 'https://store.steampowered.com/app/1551360/Forza_Horizon_5/'),
  ('hearts-of-iron-iv', 'Hearts of Iron IV', 'Stratégie militaire Seconde Guerre mondiale. (25% de réduction)', 'Hearts of Iron IV est un jeu de grande strategie focalise sur la Seconde Guerre mondiale. Gestion economique, diplomatie, doctrine militaire et production sont au coeur de l''experience pour les joueurs qui aiment la profondeur strategique.', 39.00, '2016-06-06', 'img/games/hearts-of-iron-iv.jpg', 'https://store.steampowered.com/app/394360/Hearts_of_Iron_IV/'),
  ('bodycam', 'Bodycam', 'Shooter immersif à la première personne.', 'Bodycam se distingue par son rendu tres realiste et sa perspective immersive. Le gameplay met l''accent sur la tension, les duels rapides et la precision, ce qui en fait un titre ideal pour les amateurs de shooters tactiques intenses.', 29.00, '2024-05-01', 'img/games/bodycam.jpg', 'https://store.steampowered.com/app/2406770/Bodycam/'),
  ('ghost-of-tsushima', 'Ghost of Tsushima', 'Aventure samouraï en monde ouvert.', 'Ghost of Tsushima combine exploration poetique, combats au sabre tres lisibles et narration inspiree du cinema japonais. Son monde ouvert et son ambiance sonore soignee en font une experience contemplative autant qu''action.', 59.00, '2020-07-17', 'img/games/ghost-of-tsushima.jpg', 'https://store.steampowered.com/app/2215430/Ghost_of_Tsushima_DIRECTORS_CUT/'),
  ('euro-truck-simulator-2', 'Euro Truck Simulator 2', 'Simulation de conduite de camions en Europe. (40% de réduction)', 'Euro Truck Simulator 2 propose une simulation relaxante et detaillee de transport routier en Europe. Entre gestion de flotte, optimisation de trajets et conduite longue distance, le jeu offre un rythme calme mais tres addictif.', 19.00, '2012-10-19', 'img/games/euro-truck-simulator-2.jpg', 'https://store.steampowered.com/app/227300/Euro_Truck_Simulator_2/'),
  ('helldivers-2', 'Helldivers 2', 'Coopération intense contre des hordes aliens.', 'Helldivers 2 est un shooter cooperatif nerveux ou la coordination d''equipe fait toute la difference. Les missions dynamiques, l''humour militaire satirique et les outils strategiques creent des parties chaotiques et memorables.', 39.00, '2024-02-08', 'img/games/helldivers-2.jpg', 'https://store.steampowered.com/app/553850/HELLDIVERS_2/'),
  ('dead-space-remake', 'Dead Space Remake', 'Survival horror spatial, remake du classique. (15% de réduction)', 'Dead Space Remake remet au gout du jour un classique du survival horror spatial avec une ambiance sonore glaçante et des affrontements oppressants. La progression dans l''USG Ishimura reste une reference en matiere de tension et d''immersion.', 59.00, '2023-01-27', 'img/games/dead-space-remake.jpg', 'https://store.steampowered.com/app/1693980/Dead_Space/'),
  ('wolfenstein-the-new-order', 'Wolfenstein: The New Order', 'FPS alternatif brutal contre un regime dystopique.', 'Wolfenstein: The New Order relance la serie avec une campagne nerveuse dans une uchronie dominee par un regime totalitaire. Le jeu melange action explosive, infiltration ponctuelle et narration plus marquee que les anciens episodes.', 19.00, '2014-05-20', 'img/games/wolfenstein-the-new-order.webp', 'https://store.steampowered.com/app/201810/Wolfenstein_The_New_Order/'),
  ('the-last-of-us-part-i', 'The Last of Us Part I', 'Remake moderne du premier chapitre de Joel et Ellie.', 'The Last of Us Part I reprend l''aventure originale de Joel et Ellie avec une presentation modernisee, une mise en scene plus fine et une ambiance de survie toujours tres forte. C''est le point d''entree ideal avant The Last of Us Part II.', 59.00, '2022-09-02', 'img/games/the-last-of-us-part-i.webp', 'https://store.steampowered.com/app/1888930/The_Last_of_Us_Part_I/'),
  ('resident-evil-2-remake', 'Resident Evil 2 Remake', 'Remake survival horror avec Leon et Claire a Raccoon City.', 'Resident Evil 2 Remake modernise le classique de 1998 avec une camera epaule, une ambiance plus oppressante et une exploration tendue du commissariat de Raccoon City. Leon et Claire proposent deux points de vue complementaires sur l''epidemie.', 39.00, '2019-01-25', 'img/games/resident-evil-2-remake.webp', 'https://store.steampowered.com/app/883710/Resident_Evil_2/'),
  ('resident-evil-4-remake', 'Resident Evil 4 Remake', 'Action-horror modernise avec Leon en mission de sauvetage.', 'Resident Evil 4 Remake reinterprete l''un des episodes les plus influents de la serie. Le jeu garde le rythme action-horror de l''original tout en ameliorant les combats, l''exploration, l''ambiance et la caracterisation des personnages.', 59.00, '2023-03-24', 'img/games/resident-evil-4-remake.webp', 'https://store.steampowered.com/app/2050650/Resident_Evil_4/'),
  ('resident-evil-7-biohazard', 'Resident Evil 7 Biohazard', 'Retour a l horreur en vue subjective dans la maison Baker.', 'Resident Evil 7 Biohazard ramene la serie vers une horreur plus intime avec une vue a la premiere personne. L''exploration de la maison Baker repose sur la tension, les ressources limitees et une atmosphere malsaine constante.', 19.00, '2017-01-24', 'img/games/resident-evil-7-biohazard.webp', 'https://store.steampowered.com/app/418370/Resident_Evil_7_Biohazard/'),
  ('resident-evil-village', 'Resident Evil Village', 'Suite de Biohazard entre village, chateau et creatures.', 'Resident Evil Village poursuit l''histoire d''Ethan Winters dans un village isole rempli de menaces. Le jeu combine exploration, action, horreur gothique et sequences spectaculaires avec plusieurs zones tres distinctes.', 39.00, '2021-05-07', 'img/games/resident-evil-village.webp', 'https://store.steampowered.com/app/1196590/Resident_Evil_Village/'),
  ('red-dead-redemption', 'Red Dead Redemption', 'Western culte suivant John Marston dans l Ouest americain.', 'Red Dead Redemption suit John Marston dans une histoire de redemption, de violence et de fin de l''Ouest sauvage. Son monde ouvert, ses duels, ses rencontres et son ton melancolique en ont fait un classique de Rockstar.', 49.00, '2010-05-18', 'img/games/red-dead-redemption.webp', 'https://store.steampowered.com/app/2668510/Red_Dead_Redemption/'),
  ('hollow-knight', 'Hollow Knight', 'Metroidvania exigeant dans le royaume souterrain de Hallownest.', 'Hollow Knight est un metroidvania atmospherique centre sur l''exploration, les combats precis et la decouverte progressive d''un royaume souterrain immense. Ses boss, sa carte et son ambiance en font une reference du genre.', 15.00, '2017-02-24', 'img/games/hollow-knight.webp', 'https://store.steampowered.com/app/367520/Hollow_Knight/'),
  ('hollow-knight-silksong', 'Hollow Knight: Silksong', 'Nouvelle aventure metroidvania avec Hornet.', 'Hollow Knight: Silksong place Hornet au centre d''une nouvelle aventure plus verticale et plus agile. Le jeu conserve l''esprit metroidvania du premier episode avec de nouvelles zones, ennemis, outils et defis.', 19.00, '2025-09-04', 'img/games/hollow-knight-silksong.webp', 'https://store.steampowered.com/app/1030300/Hollow_Knight_Silksong/'),
  ('metal-gear-solid', 'Metal Gear Solid', 'Classique d infiltration avec Solid Snake a Shadow Moses.', 'Metal Gear Solid a marque l''histoire du jeu d''infiltration avec sa mise en scene cinematographique, ses boss memorables et ses idees de gameplay originales. Solid Snake infiltre Shadow Moses pour stopper une menace nucleaire.', 19.00, '1998-09-03', 'img/games/metal-gear-solid.webp', 'https://store.steampowered.com/app/2131630/METAL_GEAR_SOLID_MASTER_COLLECTION_Version/'),
  ('metal-gear-solid-2-sons-of-liberty', 'Metal Gear Solid 2: Sons of Liberty', 'Suite d infiltration ambitieuse autour de Snake et Raiden.', 'Metal Gear Solid 2: Sons of Liberty pousse plus loin l''infiltration, l''intelligence ennemie et les themes politiques de la serie. Sa narration surprenante et ses systemes interactifs restent marquants.', 19.00, '2001-11-13', 'img/games/metal-gear-solid-2-sons-of-liberty.webp', 'https://store.steampowered.com/app/2131640/METAL_GEAR_SOLID_2_Sons_of_Liberty__Master_Collection_Version/'),
  ('metal-gear-solid-4-guns-of-the-patriots', 'Metal Gear Solid 4: Guns of the Patriots', 'Conclusion epique de l histoire de Solid Snake.', 'Metal Gear Solid 4: Guns of the Patriots conclut l''arc de Solid Snake avec une aventure tres cinematographique. Le jeu melange infiltration, action, gadgets avances et nombreux rappels aux episodes precedents.', 19.00, '2008-06-12', 'img/games/metal-gear-solid-4-guns-of-the-patriots.webp', 'https://www.konami.com/mg/mgs4/'),
  ('metal-gear-solid-v-the-phantom-pain', 'Metal Gear Solid V: The Phantom Pain', 'Infiltration en monde ouvert avec Big Boss.', 'Metal Gear Solid V: The Phantom Pain transforme l''infiltration en bac a sable ouvert. Le joueur choisit ses approches, recrute des soldats, developpe Mother Base et execute des missions avec une grande liberte tactique.', 19.00, '2015-09-01', 'img/games/metal-gear-solid-v-the-phantom-pain.webp', 'https://store.steampowered.com/app/287700/METAL_GEAR_SOLID_V_THE_PHANTOM_PAIN/'),
  ('god-of-war-2018', 'God of War', 'Reinvention nordique de Kratos avec Atreus.', 'God of War reinvente la saga avec une camera plus proche, une narration plus intime et un systeme de combat axe sur la hache Leviathan. Le voyage de Kratos et Atreus pose les bases de l''arc nordique.', 49.00, '2018-04-20', 'img/games/god-of-war-2018.webp', 'https://store.steampowered.com/app/1593500/God_of_War/'),
  ('the-legend-of-zelda-ocarina-of-time', 'The Legend of Zelda: Ocarina of Time', 'Aventure culte de Link entre enfance, temps et donjons.', 'The Legend of Zelda: Ocarina of Time est l''un des jeux d''aventure les plus importants de Nintendo. Il suit Link dans une quete a travers Hyrule, avec donjons, enigmes, voyage temporel et musiques jouees a l''ocarina.', 59.00, '1998-11-21', 'img/games/the-legend-of-zelda-ocarina-of-time.webp', 'https://www.nintendo.com/us/store/products/nintendo-64-nintendo-switch-online-switch/')
ON DUPLICATE KEY UPDATE
  titre = VALUES(titre),
  description_courte = VALUES(description_courte),
  description_longue = VALUES(description_longue),
  prix = VALUES(prix),
  date_sortie = VALUES(date_sortie),
  image_url = VALUES(image_url),
  download_url = VALUES(download_url),
  actif = 1;
